// Saved choice first; otherwise Spanish for Spanish-speaking browsers and English for everyone else.
let lang = localStorage.getItem('lj_lang') ||
  ((navigator.language || 'es').toLowerCase().startsWith('es') ? 'es' : 'en');

export function getLang() { return lang; }
export function setLang(l) { lang = l === 'en' ? 'en' : 'es'; localStorage.setItem('lj_lang', lang); document.documentElement.lang = lang; }

export function t(key, vars = {}) {
  const s = S[lang][key] ?? S.es[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? ''));
}

export function locale() { return lang === 'en' ? 'en-US' : 'es-CL'; }
